function wireSpeed(charts) {
  var input = document.querySelector('#speed')
  var label = document.querySelector('#speed-value')
  if (!input) return
  input.addEventListener('input', function () {
    MORPH_SPEED = parseInt(input.value, 10)
    if (label) label.textContent = MORPH_SPEED
    charts.forEach(function (chart) {
      if (!chart) return
      chart.updateOptions(
        { chart: { animations: { chartTypeMorph: { speed: MORPH_SPEED } } } },
        false,
        false,
      )
    })
  })
}

